head.script:
scwin.onpageload = function() {
};

	scwin.checkVal = function() {
		var dateString = WebSquare.wUnit.getDomById('wq_uuid_1_calendar_currentDate').innerText;
		var day = parseInt(dateString.substring(8, 10));
		console.log("1day :" + day)
		var todayString = document.getElementsByClassName('w2calendar_selected')[0].innerText;
		return day == parseInt(todayString);
		console.log("2day :" + day)
	}
	scwin.unitTest = function() {
		//Init test
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_img').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_calendar_picker_header_dynamic_entity').click()");
		WebSquare.wUnit.addCommand("pause", "400");	
		WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_go_today')[0].click()");
		WebSquare.wUnit.addCommand("pause", "400");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run and Stop unit Test
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
